from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = max(set(vals), key=vals.count)
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            ys = [y for y,x in cells]; xs = [x for y,x in cells]
            r0,r1,c0,c1 = min(ys),max(ys),min(xs),max(xs)
            area = (r1-r0+1)*(c1-c0+1)
            # Non-background components that occupy most of a rectangle are the objects;
            # fill their bounding boxes to remove overlaid speckle noise.
            if area >= 4 and len(cells) / area >= 0.60:
                boxes.append((color,r0,r1,c0,c1))
    out = [[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in boxes:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                out[r][c] = color
    return out

