from collections import Counter

def transform(grid):
    """Recolor the unique connected object whose size matches another color's population."""
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    bg = freq.most_common(1)[0][0]
    # Connected monochrome components, using edge adjacency.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color, cells))
    out = [row[:] for row in grid]
    # Find a non-background component whose area equals the total count of
    # another non-background color; recolor it to that color.
    candidates = []
    for color, cells in comps:
        for target, n in freq.items():
            if target != bg and target != color and len(cells) == n:
                candidates.append((color, target, cells))
    if len(candidates) == 1:
        _, target, cells = candidates[0]
        for r, c in cells:
            out[r][c] = target
    return out

